import { toggleNotifications } from './actions'
import {
  getCurrentUserId,
  getNotificationPreference,
} from '@/lib/preferences'

export default async function Home() {
  const userId = await getCurrentUserId()
  const enabled = await getNotificationPreference(userId)

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotifications}>
        <p>
          Notifications are <strong>{enabled ? 'on' : 'off'}</strong>
        </p>
        <button type="submit">
          {enabled ? 'Turn notifications off' : 'Turn notifications on'}
        </button>
      </form>
    </main>
  )
}

